$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $Root
function Write-Utf8([string]$Path,[string]$Base64) {
  $full=Join-Path $Root $Path; New-Item -ItemType Directory -Force -Path (Split-Path -Parent $full)|Out-Null
  [IO.File]::WriteAllBytes($full,[Convert]::FromBase64String($Base64))
}
Write-Utf8 "scripts/n-mega5-level-progression.mjs" ""
Write-Utf8 "src/certification/player-readiness/nMega5Progression.test.ts" ""
if(Test-Path (Join-Path $Root 'patch')){Remove-Item (Join-Path $Root 'patch') -Recurse -Force}
if(Test-Path (Join-Path $Root 'payload')){Remove-Item (Join-Path $Root 'payload') -Recurse -Force}
Write-Host "N-MEGA5 dosyalari uygulandi."
node .\scripts
-mega5-level-progression.mjs
if($LASTEXITCODE -ne 0){throw "N-MEGA5 audit RED"}
npm.cmd exec vitest run src/certification/player-readiness/nMega5Progression.test.ts src/certification/matrix/levelUpProgressionScenarioMatrix.test.ts src/certification/oracle/progressionOracle.test.ts src/certification/oracle/levelUpProgressionOracle.test.ts src/certification/differential/levelUpProgressionDifferential.test.ts src/core/rulesets/classProgression.test.ts src/core/rulesets/classProgressionAudit.test.ts src/core/rulesets/level20Certification.test.ts src/core/rulesets/level20Certification.integration.test.ts src/core/rulesets/martialOfficialProgression.test.ts src/core/rulesets/halfCasterOfficialProgression.test.ts src/core/rulesets/clericDruidOfficialProgression.test.ts src/core/rulesets/bardSorcererOfficialProgression.test.ts src/core/rulesets/warlockWizardOfficialProgression.test.ts src/core/rulesets/subclassOfficialProgressionFixes.test.ts src/features/characters/levelUpCalculator.test.ts src/features/characters/levelUpHistory.test.ts
if($LASTEXITCODE -ne 0){throw "N-MEGA5 regression tests failed"}
npm.cmd run build
if($LASTEXITCODE -ne 0){throw "N-MEGA5 build failed"}
Write-Host "N-MEGA5 GREEN"
